insert into natural_english_private.catalogue(module,senses,questions) values
('advanced-native-006', '["phrase"]'::jsonb, '{"advanced-native-006-v1-audio":{"type":"mc","answers":["她已答應主持，後來卻退出。"],"options":["她尚未收到主持邀請。","她如期完成了主持工作。","她只更改了音樂會的日期。","她已答應主持，後來卻退出。"]},"advanced-native-006-v2-reply":{"type":"mc","answers":["He has another commitment that weekend.","He backed out when the forecast changed.","He no longer feels ready to guide the group.","The weather made him change his mind."],"options":["He has another commitment that weekend.","He backed out when the forecast changed.","He no longer feels ready to guide the group.","The weather made him change his mind."]},"advanced-native-006-v1-scene":{"type":"mc","answers":["She backed out of the school play."],"options":["She backed out of the school play.","She put off accepting a role in the play.","She completed her role in the play."]},"advanced-native-006-v1-contrast":{"type":"mc","answers":["他剛收到邀請就婉拒，從未答應參與。"],"options":["他報名比賽後因受傷退出。","他剛收到邀請就婉拒，從未答應參與。","她答應帶隊，臨行前改變主意。"]},"advanced-native-006-v1-branch":{"type":"mc","answers":["If you need to back out, tell the organisers today so they can find someone else."],"options":["Wait until the fundraiser ends before you tell anyone you cannot come.","If you need to back out, tell the organisers today so they can find someone else.","You backed out when you declined their first invitation."]},"advanced-native-006-v1-final":{"type":"open","answers":["I have to back out of painting the room this weekend because I am ill. I can help find a replacement.","I agreed to help paint the room, but I need to back out now. Could Maya take over?"],"options":[]}}'::jsonb),
('advanced-native-007', '["phrase"]'::jsonb, '{"advanced-native-007-v1-audio":{"type":"mc","answers":["他們合力撐過艱難的第一週。"],"options":["他們合力撐過艱難的第一週。","他們在訓練開始前退出。","訓練從頭到尾都很輕鬆。","他們在一週內變得比別人強。"]},"advanced-native-007-v2-reply":{"type":"mc","answers":["We got through it by helping one another.","We shared the work when it became too much.","We kept going even though we were tired.","We asked for help and finished the week."],"options":["We got through it by helping one another.","We shared the work when it became too much.","We kept going even though we were tired.","We asked for help and finished the week."]},"advanced-native-007-v1-scene":{"type":"mc","answers":["They got through it."],"options":["They dropped out before it was over.","They got through it.","They put it off until the following week."]},"advanced-native-007-v1-contrast":{"type":"mc","answers":["她輕鬆走過一段平常的短走廊，沒有困難或壓力。"],"options":["他在朋友協助下熬過艱難的康復期。","他們頂着壓力完成連續三天的考試。","她輕鬆走過一段平常的短走廊，沒有困難或壓力。"]},"advanced-native-007-v1-branch":{"type":"mc","answers":["It sounds hard, but you can get through it one day at a time. Ask us for help if you need it."],"options":["It sounds hard, but you can get through it one day at a time. Ask us for help if you need it.","You have already got through it, so the next three days are over.","If you get through it, that means the rehearsals were never difficult."]},"advanced-native-007-v1-final":{"type":"open","answers":["It was a stressful week of moving and exams, but she got through it with help from her friends.","She had a hard week of exams and moving, yet she got through it by making a simple plan with her friends."],"options":[]}}'::jsonb),
('advanced-native-008', '["phrase"]'::jsonb, '{"advanced-native-008-v1-audio":{"type":"mc","answers":["球隊從落敗中學習，之後變得更有實力。"],"options":["球隊退出了下一季的賽事。","球隊從落敗中學習，之後變得更有實力。","球隊只是完成了比賽，沒有任何改變。","球隊一開始便比所有對手強。"]},"advanced-native-008-v2-reply":{"type":"mc","answers":["They came out stronger after learning from the failure.","They learned to test ideas earlier.","They became better at working under pressure.","They used the lessons to plan more carefully."],"options":["They came out stronger after learning from the failure.","They learned to test ideas earlier.","They became better at working under pressure.","They used the lessons to plan more carefully."]},"advanced-native-008-v1-scene":{"type":"mc","answers":["They came out stronger."],"options":["They decided never to compete again.","They came out stronger.","They merely got through the first contest."]},"advanced-native-008-v1-contrast":{"type":"mc","answers":["他熬過難關，但至今沒有顯示能力或應對方式有所改變。"],"options":["球隊經歷挫敗後改進合作，下一季更有韌性。","他熬過難關，但至今沒有顯示能力或應對方式有所改變。","她從首次失敗中學會新方法，下一次做得更好。"]},"advanced-native-008-v1-branch":{"type":"mc","answers":["I hope you come out stronger in the end, but take the time you need to recover."],"options":["You should be grateful for the injury because every setback makes people stronger.","I hope you come out stronger in the end, but take the time you need to recover.","This setback has already made you stronger, so you no longer need support."]},"advanced-native-008-v1-final":{"type":"open","answers":["The debate team came out stronger after losing the final because they changed how they prepared.","They took the judges’ feedback seriously and came out stronger the following term."],"options":[]}}'::jsonb),
('advanced-native-009', '["phrase"]'::jsonb, '{"advanced-native-009-v1-audio":{"type":"mc","answers":["週末課程幫助她邁向設計實習。"],"options":["她已經完成整個職業目標。","她在週末課程中學習砌石階。","週末課程幫助她邁向設計實習。","週末課程阻止她申請實習。"]},"advanced-native-009-v2-reply":{"type":"mc","answers":["It was a stepping stone towards her teaching career.","It gave her experience working with children.","It helped her build confidence before applying to schools.","She gained skills she could use later."],"options":["It was a stepping stone towards her teaching career.","It gave her experience working with children.","It helped her build confidence before applying to schools.","She gained skills she could use later."]},"advanced-native-009-v1-scene":{"type":"mc","answers":["A stepping stone towards stage work."],"options":["The final goal of her entire career.","A stepping stone towards stage work.","A barrier that stopped all progress."]},"advanced-native-009-v1-contrast":{"type":"mc","answers":["計劃被無故取消，當事人失去學習機會，目標因而受阻。"],"options":["學生透過短期實習學到技能，之後可申請相關工作。","她先參與校報，累積寫作經驗，再申請編輯職位。","計劃被無故取消，當事人失去學習機會，目標因而受阻。"]},"advanced-native-009-v1-branch":{"type":"mc","answers":["This café job could be a stepping stone towards running your own business if it helps you learn how a café works."],"options":["Only someone who already owns a café can gain experience for that goal.","This café job could be a stepping stone towards running your own business if it helps you learn how a café works.","This job guarantees that you will own a café as soon as you finish it."]},"advanced-native-009-v1-final":{"type":"open","answers":["Volunteering at the community paper could be a stepping stone towards a journalism career.","The newspaper role is a stepping stone because it lets her practise interviewing people."],"options":[]}}'::jsonb),
('advanced-native-010', '["phrase"]'::jsonb, '{"advanced-native-010-v1-audio":{"type":"mc","answers":["缺少許可證阻礙了活動籌備。"],"options":["節日活動已順利完成。","有人被地上的石頭絆倒。","缺少許可證阻礙了活動籌備。","許可證讓活動更快獲批。"]},"advanced-native-010-v2-reply":{"type":"mc","answers":["The missing permit is a stumbling block.","The council has not approved the route.","They still need permission before they can build.","The application is still under review."],"options":["The missing permit is a stumbling block.","The council has not approved the route.","They still need permission before they can build.","The application is still under review."]},"advanced-native-010-v1-scene":{"type":"mc","answers":["The missing computers are a stumbling block."],"options":["The missing computers are a stepping stone.","The missing computers have no effect on when the club can start.","The missing computers are a stumbling block."]},"advanced-native-010-v1-contrast":{"type":"mc","answers":["所需許可已提早批出，團隊得以如期開始。"],"options":["關鍵材料遲到，導致排練無法進行。","所需許可已提早批出，團隊得以如期開始。","申請一直未獲批，項目因此停滯。"]},"advanced-native-010-v1-branch":{"type":"mc","answers":["The budget gap is a stumbling block. Could we apply for a small grant?"],"options":["The budget gap is a stepping stone because it moves the project forward.","The project is impossible now; a stumbling block can never be overcome.","The budget gap is a stumbling block. Could we apply for a small grant?"]},"advanced-native-010-v1-final":{"type":"open","answers":["The late delivery is a stumbling block, so we will borrow tools for now.","The missing soil is our biggest stumbling block. We will ask a local garden centre for help."],"options":[]}}'::jsonb)
